      }
      button { font: inherit; }
      button:focus-visible { outline: 2px solid var(--tangerine); outline-offset: 3px; }

      .oracle-panel {
        position: relative;
        width: 100%;
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.95);
        border-radius: 22px;
        background:
          radial-gradient(circle at 12px 12px, rgba(255, 148, 66, 0.13) 1.2px, transparent 1.3px) 0 0 / 24px 24px,
          radial-gradient(circle at 88% -12%, rgba(255, 196, 107, 0.34), transparent 58%),
          radial-gradient(circle at 6% 110%, rgba(255, 140, 80, 0.2), transparent 52%),
          linear-gradient(150deg, #fffdf6 0%, #fff4dc 55%, #ffebcb 100%);
        box-shadow: var(--shadow), inset 0 1px 0 #fff;
        isolation: isolate;
      }
      .oracle-panel::before {
        content: '';
        position: absolute;
        top: 0;
        right: 30px;
