      }

      .oracle-header {
        position: relative;
        z-index: 1;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
        gap: 12px;
        min-height: 78px;
        padding: 14px 16px 13px;
        border-bottom: 1px dashed rgba(226, 146, 72, 0.4);
        background: rgba(255, 253, 246, 0.42);
      }
      .jin-badge {
        position: relative;
        width: 52px;
        height: 52px;
        flex: 0 0 auto;
        display: block;
        filter: drop-shadow(0 5px 12px rgba(255, 148, 66, 0.38));
      }
      .badge-rays {
        transform-box: fill-box;
        transform-origin: center;
        animation: badge-spin 30s linear infinite;
      }
      @keyframes badge-spin { to { transform: rotate(360deg); } }

      .title-block { min-width: 0; }
      .eyebrow {
        margin-bottom: 2px;
        color: var(--tangerine);
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }
      h1 {
        margin: 0;
        color: var(--caramel);
        font-size: clamp(19px, 4vw, 24px);
        font-weight: 800;
        line-height: 1.08;
        letter-spacing: 0.03em;
      }
      .subtitle {
        margin: 4px 0 0;
        overflow: hidden;
        color: var(--muted);
        font-size: 10px;
