      }

      .mode-toggle {
        min-width: 116px;
        display: grid;
        grid-template-columns: minmax(0, 1fr) 34px;
        align-items: center;
        gap: 9px;
        padding: 7px 8px 7px 10px;
        border: 1px solid var(--line);
        border-radius: 12px;
        color: var(--muted);
        background: rgba(255, 253, 246, 0.72);
        cursor: pointer;
        text-align: left;
        transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
      }
      .mode-toggle:hover { border-color: rgba(226, 132, 52, 0.45); background: rgba(255, 255, 255, 0.9); }
      .mode-toggle:active { transform: scale(0.98); }
      .mode-copy { display: grid; gap: 1px; }
      .mode-copy strong { color: var(--caramel); font-size: 11px; font-weight: 750; }
      .mode-copy small { color: var(--muted); font-size: 8px; white-space: nowrap; }
      .switch-track {
        width: 34px;
        height: 20px;
        display: block;
        padding: 2px;
        border: 1px solid rgba(200, 130, 60, 0.35);
        border-radius: 999px;
        background: #f3dfc4;
        transition: background 180ms ease, border-color 180ms ease;
      }
      .switch-knob {
        width: 14px;
        height: 14px;
        display: block;
        border-radius: 50%;
        background: #fff;
        box-shadow: 0 2px 5px rgba(140, 80, 30, 0.22);
        transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1), background 180ms ease;
      }
      .mode-toggle.is-active .switch-track { border-color: var(--tangerine); background: var(--sun); }
      .mode-toggle.is-active .switch-knob { background: #fffdf6; transform: translateX(14px); }

      .option-region { position: relative; z-index: 1; padding: 13px 14px 12px; }
      .option-region::before {
        content: '';
        position: absolute;
        top: 22px;
        bottom: 22px;
        left: 35px;
        width: 1px;
        background: repeating-linear-gradient(to bottom, rgba(226, 132, 52, 0.4) 0 4px, transparent 4px 8px);
        pointer-events: none;
      }
      .option-list {
        max-height: min(430px, 68vh);
        display: grid;
        gap: 8px;
        margin: 0;
        padding: 0 3px 0 0;
        overflow-x: hidden;
        overflow-y: auto;
        list-style: none;
        scrollbar-color: rgba(226, 132, 52, 0.35) transparent;
        scrollbar-width: thin;
      }
      .option-list::-webkit-scrollbar { width: 5px; }
      .option-list::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(226, 132, 52, 0.35); }

      .option-btn {
        position: relative;
        width: 100%;
        min-height: 52px;
        display: grid;
        grid-template-columns: 32px minmax(0, 1fr) 24px;
        align-items: center;
        gap: 9px;
        padding: 8px 10px 8px 7px;
        overflow: hidden;
        border: 1px solid rgba(226, 146, 72, 0.26);
        border-radius: 13px;
        color: var(--caramel);
        background: rgba(255, 253, 246, 0.78);
        box-shadow: 0 2px 8px rgba(214, 124, 48, 0.08);
        cursor: pointer;
        text-align: left;
        opacity: 0;
        transform: translateY(6px);
        animation: option-arrive 320ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        animation-delay: var(--delay, 0ms);
        transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease, transform 160ms ease;
      }
      .option-btn::after {
        content: '';
        position: absolute;
        inset: 0 auto 0 0;
        width: 3px;
        border-radius: 13px 0 0 13px;
        background: linear-gradient(var(--sun), var(--tangerine));
        transition: width 160ms ease, background 160ms ease;
      }
      .option-btn:hover {
        border-color: rgba(226, 132, 52, 0.5);
        background: rgba(255, 255, 255, 0.97);
        box-shadow: 0 7px 16px rgba(224, 122, 42, 0.16);
        transform: translateY(-1px);
      }
      .option-btn:hover::after,
      .option-btn.is-selected::after { width: 5px; background: var(--melon); }
      .option-btn:active { transform: translateY(0) scale(0.99); }
      .option-btn.is-selected { border-color: rgba(226, 132, 52, 0.58); background: #fff; }
      .option-index {
        position: relative;
        z-index: 1;
        width: 29px;
        height: 29px;
        display: grid;
        place-items: center;
        border: 1px solid rgba(255, 255, 255, 0.65);
        border-radius: 10px 10px 10px 4px;
        color: #fffdf6;
        background: linear-gradient(145deg, #ffc46b, #ff9442);
        font: 700 9px/1 ui-monospace, 'SFMono-Regular', Consolas, monospace;
        box-shadow: 0 2px 6px rgba(224, 122, 42, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.4);
      }
      .option-text {
        min-width: 0;
        font-size: 13px;
        line-height: 1.52;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }
      .option-paw {
        color: var(--sun);
        font-size: 15px;
        text-align: center;
        opacity: 0.75;
        transform: rotate(-12deg);
        transition: color 160ms ease, opacity 160ms ease, transform 160ms ease;
      }
      .option-btn:hover .option-paw,
      .option-btn.is-selected .option-paw { color: var(--melon); opacity: 1; transform: rotate(0deg) scale(1.1); }

      .empty-state {
        min-height: 98px;
        display: grid;
        place-items: center;
        gap: 5px;
        padding: 20px;
        border: 1px dashed rgba(226, 146, 72, 0.4);
        border-radius: 14px;
        color: var(--muted);
        background: rgba(255, 253, 246, 0.55);
        font-size: 11px;
        text-align: center;
      }
      .empty-state strong { color: var(--caramel); font-size: 13px; }
      .oracle-footer {
        position: relative;
        z-index: 1;
        min-height: 34px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 7px 16px 9px;
        color: var(--muted);
        font-size: 9px;
      }
      .oracle-footer span:first-child::before { content: '✿'; margin-right: 5px; color: var(--tangerine); }
      .status { overflow: hidden; text-align: right; text-overflow: ellipsis; white-space: nowrap; }
      .status.is-error { color: #d9553f; }

      @keyframes option-arrive { to { opacity: 1; transform: translateY(0); } }

      @media (max-width: 520px) {
        body { padding: 3px; }
        .oracle-panel { border-radius: 18px; }
        .oracle-header { grid-template-columns: auto minmax(0, 1fr); gap: 10px; padding: 13px 12px 11px; }
        .jin-badge { width: 48px; height: 48px; }
        .mode-toggle { grid-column: 1 / -1; width: 100%; min-height: 42px; }
        .mode-copy { display: flex; align-items: baseline; gap: 7px; }
        .option-region { padding: 10px; }
        .option-region::before { left: 29px; }
        .option-btn { grid-template-columns: 30px minmax(0, 1fr) 18px; gap: 7px; min-height: 50px; border-radius: 11px; }
        .option-text { font-size: 12px; }
        .oracle-footer { padding-inline: 12px; }
      }

      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after {
          scroll-behavior: auto !important;
          animation-duration: 0.01ms !important;
          animation-delay: 0ms !important;
          transition-duration: 0.01ms !important;
        }
        .badge-rays { animation: none !important; }
      }
    </style>
