            </linearGradient>
            <linearGradient id="jinRing" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stop-color="#ffe3b3"/>
              <stop offset="1" stop-color="#ff6b5e"/>
            </linearGradient>
          </defs>
          <g class="badge-rays">
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(0 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(45 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(90 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(135 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(180 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(225 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(270 50 50)"/>
            <line x1="50" y1="7" x2="50" y2="17" stroke="#ffb45e" stroke-width="4" stroke-linecap="round" transform="rotate(315 50 50)"/>
          </g>
          <circle cx="50" cy="50" r="34" fill="none" stroke="url(#jinRing)" stroke-width="5"/>
          <circle cx="50" cy="50" r="29" fill="url(#jinBg)"/>
          <circle cx="50" cy="50" r="21" fill="none" stroke="#fff9ee" stroke-opacity="0.55" stroke-width="1.6" stroke-dasharray="2.5 3.5"/>
          <text x="50" y="60" text-anchor="middle" font-size="32" font-weight="800" fill="#fff9ee" font-family="'Microsoft YaHei UI','PingFang SC',sans-serif">夏</text>
        </svg>
        <div class="title-block">
          <div class="eyebrow">Summer oracle · 夏瑾</div>
          <h1 id="oracle-title">请选一个回应吧</h1>
          <p class="subtitle">夏天的太阳升起来了，然后再也不会落下去</p>
        </div>
        <button class="mode-toggle" id="directSendToggle" type="button" aria-pressed="true">
          <span class="mode-copy">
            <strong id="modeTitle">直接发送</strong>
            <small id="modeHint">点选后立即发出</small>
          </span>
          <span class="switch-track" aria-hidden="true"><span class="switch-knob"></span></span>
        </button>
      </header>

      <section class="option-region" aria-label="回应选项">
        <ol class="option-list" id="listRoot"></ol>
      </section>

      <footer class="oracle-footer">
        <span id="optionCount">正在读取神谕…</span>
        <span class="status" id="statusText" role="status" aria-live="polite">挑一个顺眼的</span>
      </footer>
    </main>

    <script>
      (() => {
        'use strict';

        const rawData = document.getElementById('raw-data');
        const listRoot = document.getElementById('listRoot');
        const toggle = document.getElementById('directSendToggle');
        const modeTitle = document.getElementById('modeTitle');
        const modeHint = document.getElementById('modeHint');
        const optionCount = document.getElementById('optionCount');
        const statusText = document.getElementById('statusText');
        const panel = document.querySelector('.oracle-panel');
        let directSend = true;
        let selectedButton = null;
        let resizeFrame = 0;

        function getSillyTavern() {
          try {
            return window.top?.SillyTavern || window.parent?.SillyTavern || null;
          } catch (error) {
            console.warn('[Summer Oracle] SillyTavern context is unavailable', error);
            return null;
          }
        }

        function setStatus(message, isError = false) {
          statusText.textContent = message;
          statusText.classList.toggle('is-error', isError);
        }

        function updateHeight() {
          resizeFrame = 0;
          if (window.parent && window.parent !== window) {
            window.parent.postMessage({ type: 'resizeIframe', height: document.body.scrollHeight }, '*');
          }
        }

        function scheduleHeightUpdate() {
          if (resizeFrame) cancelAnimationFrame(resizeFrame);
          resizeFrame = requestAnimationFrame(updateHeight);
        }

        function optionTextFromHtml(html) {
          const template = document.createElement('template');
          template.innerHTML = html;
          return (template.content.textContent || '').trim();
        }

        function renderEmpty(title, detail) {
          const empty = document.createElement('li');
          empty.className = 'empty-state';
          const heading = document.createElement('strong');
          heading.textContent = title;
          const copy = document.createElement('span');
          copy.textContent = detail;
          empty.append(heading, copy);
          listRoot.replaceChildren(empty);
          optionCount.textContent = '没有可用选项';
          scheduleHeightUpdate();
        }

        function parseAndRender() {
          const source = rawData.innerHTML;
          const optionsMatch = source.match(/<SUOT\b[^>]*>([\s\S]*?)<\/SUOT>/i);
          if (!optionsMatch) {
            renderEmpty('还没收到回应选项', '请检查模型输出中是否包含 <SUOT> 标签。');
            return;
          }

          const entries = [];
          for (const rawLine of optionsMatch[1].split(/\r?\n/)) {
            const text = optionTextFromHtml(rawLine).replace(/^\s*\d+\s*[.、.)）:：]\s*/, '');
            if (text) entries.push(text);
          }

          if (!entries.length) {
            renderEmpty('选项列表是空的', '请在 <SUOT> 中至少写入一行选项。');
            return;
          }

          const fragment = document.createDocumentFragment();
          entries.forEach((text, index) => {
            const item = document.createElement('li');
            const button = document.createElement('button');
            const number = document.createElement('span');
            const copy = document.createElement('span');
            const sun = document.createElement('span');

            button.type = 'button';
            button.className = 'option-btn';
            button.style.setProperty('--delay', `${Math.min(index * 42, 252)}ms`);
            button.setAttribute('aria-label', `选择回应 ${index + 1}：${text}`);
            number.className = 'option-index';
            number.textContent = String(index + 1).padStart(2, '0');
            number.setAttribute('aria-hidden', 'true');
            copy.className = 'option-text';
            copy.textContent = text;
            sun.className = 'option-paw';
            sun.textContent = '☀';
            sun.setAttribute('aria-hidden', 'true');
            button.append(number, copy, sun);
            button.addEventListener('click', () => handleSelect(text, button));
            item.appendChild(button);
            fragment.appendChild(item);
          });

          listRoot.replaceChildren(fragment);
          optionCount.textContent = `共 ${entries.length} 条回应`;
          scheduleHeightUpdate();
        }

        function updateToggleUi() {
          toggle.classList.toggle('is-active', directSend);
          toggle.setAttribute('aria-pressed', String(directSend));
          modeTitle.textContent = directSend ? '直接发送' : '仅填入';
          modeHint.textContent = directSend ? '点选后立即发出' : '点选后留在输入框';
        }

        function initToggle() {
          try {
            const st = getSillyTavern();
            const context = st?.getContext?.();
            const stored = context?.extensionSettings?.XiaJin?.directSend;
            if (typeof stored === 'boolean') directSend = stored;
          } catch (error) {
            console.warn('[Summer Oracle] Failed to read direct-send setting', error);
          }

          updateToggleUi();
          toggle.addEventListener('click', () => {
            directSend = !directSend;
            updateToggleUi();
            setStatus(directSend ? '已开启直接发送' : '已切换为仅填入');

            try {
              const st = getSillyTavern();
              const context = st?.getContext?.();
              if (!context) return;
              context.extensionSettings ||= {};
              context.extensionSettings.XiaJin ||= {};
              context.extensionSettings.XiaJin.directSend = directSend;
              if (typeof st?.saveSettingsDebounced === 'function') st.saveSettingsDebounced();
              else context.saveSettingsDebounced?.();
            } catch (error) {
              console.error('[Summer Oracle] Failed to save direct-send setting', error);
              setStatus('模式已切换，但未能保存设置', true);
            }
            scheduleHeightUpdate();
          });
        }

        function removeOwnIframe() {
          try {
            const frames = window.parent?.document?.querySelectorAll('iframe') || [];
            for (const frame of frames) {
              if (frame.contentWindow === window) {
                frame.remove();
                break;
              }
            }
          } catch (error) {
            console.warn('[Summer Oracle] Failed to close option frame', error);
          }
        }

        function handleSelect(text, button) {
          try {
            const parentDocument = window.parent?.document;
            const textarea = parentDocument?.getElementById('send_textarea');
            if (!textarea) {
              setStatus('未找到酒馆输入框', true);
              return;
            }

            selectedButton?.classList.remove('is-selected');
            selectedButton = button;
            selectedButton.classList.add('is-selected');

            const valueSetter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
            if (valueSetter) valueSetter.call(textarea, text);
            else textarea.value = text;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
            textarea.dispatchEvent(new Event('change', { bubbles: true }));
            textarea.focus();

            if (!directSend) {
              setStatus('已填入酒馆输入框');
              return;
            }

            const st = getSillyTavern();
            const context = st?.getContext?.();
            if (typeof context?.generate === 'function') context.generate();
            else {
              const sendButton = parentDocument.getElementById('send_but');
              if (!sendButton) throw new Error('Send button is unavailable');
              sendButton.click();
            }
            removeOwnIframe();
          } catch (error) {
            console.error('[Summer Oracle] Failed to apply option', error);
            setStatus('未能应用这条回应，请检查控制台', true);
          }
        }

        window.addEventListener('DOMContentLoaded', () => {
          parseAndRender();
          initToggle();
          scheduleHeightUpdate();
          window.addEventListener('resize', scheduleHeightUpdate);
          if ('ResizeObserver' in window) new ResizeObserver(scheduleHeightUpdate).observe(panel);
          document.fonts?.ready?.then(scheduleHeightUpdate);
        });
      })();
    </script>
  </body>
